static NSString *canonical(NSString *p){return p.stringByStandardizingPath.stringByResolvingSymlinksInPath;}
static NSString *sha(const void *p,size_t n){CC_SHA256_CTX c;CC_SHA256_Init(&c);const uint8_t *v=p;while(n){size_t k=MIN(n,1048576u);CC_SHA256_Update(&c,v,(CC_LONG)k);v+=k;n-=k;}uint8_t d[32];CC_SHA256_Final(d,&c);char s[65];for(unsigned i=0;i<32;i++)snprintf(s+i*2,3,"%02x",d[i]);return[NSString stringWithUTF8String:s];}
