static BOOL finite_f32(const void *p,size_t n){const uint32_t *v=p;for(size_t i=0;i<n/4;i++)if((v[i]&0x7f800000u)==0x7f800000u)return NO;return YES;}
static BOOL written(const void *p,size_t n){const uint32_t *v=p;for(size_t i=0;i<n/4;i++)if(v[i]==0xa5a5a5a5u)return NO;return YES;}
static double median(NSArray *a){NSArray *s=[a sortedArrayUsingSelector:@selector(compare:)];NSUInteger n=s.count;need(n>0,"median samples");return n%2?[s[n/2]doubleValue]:([s[n/2-1]doubleValue]+[s[n/2]doubleValue])*.5;}
static NSData *payload(NSDictionary *c,NSString *key,NSString *base,size_t bytes){NSDictionary *d=c[key];need([d isKindOfClass:NSDictionary.class],"payload descriptor");NSString *p=d[@"path"];need([p isKindOfClass:NSString.class],"payload path");if(!p.isAbsolutePath)p=[base stringByAppendingPathComponent:p];NSData *v=read_file(canonical(p));need(v.length==bytes&&integer(d[@"bytes"],UINT64_MAX,"payload extent")==bytes&&[sha(v.bytes,v.length)isEqual:d[@"sha256"]],"payload exact bytes/SHA");return v;}

typedef struct { myds_metal_buffer_t *owner,*body;size_t bytes; } guarded;
static guarded buffer(size_t bytes,const void *initial){guarded b={.bytes=bytes};b.owner=myds_metal_buffer_alloc(bytes+G*2);need(b.owner!=NULL,"guarded Metal allocation");memset(myds_metal_buffer_data(b.owner),0xa5,bytes+G*2);b.body=myds_metal_buffer_sub_view(b.owner,G,bytes);need(b.body!=NULL,"guarded view");if(initial)memcpy(myds_metal_buffer_data(b.body),initial,bytes);return b;}
static BOOL guards(guarded b){const uint8_t *p=myds_metal_buffer_data(b.owner);for(unsigned i=0;i<G;i++)if(p[i]!=0xa5||p[G+b.bytes+i]!=0xa5)return NO;return YES;}
static void poison(guarded b){memset(myds_metal_buffer_data(b.body),0xa5,b.bytes);}
static void release_buffer(guarded b){myds_metal_buffer_free(b.body);myds_metal_buffer_free(b.owner);}
static void dump_buffer(NSString *name,guarded b){raw([name stringByAppendingString:@".f32"],myds_metal_buffer_data(b.body),b.bytes);uint8_t g[G*2];const uint8_t *p=myds_metal_buffer_data(b.owner);memcpy(g,p,G);memcpy(g+G,p+G+b.bytes,G);raw([name stringByAppendingString:@".guards"],g,sizeof(g));}
static void dump_guard(NSString *name,guarded b){uint8_t g[G*2];const uint8_t *p=myds_metal_buffer_data(b.owner);memcpy(g,p,G);memcpy(g+G,p+G+b.bytes,G);raw([name stringByAppendingString:@".guards"],g,sizeof(g));}
