typedef struct { NSDictionary *record;NSData *x,*ids,*weights,*captured;guarded xb,ib,wb,out;unsigned rows,index;BOOL derived; } fixture;
static void validate(fixture *f){need(guards(f->xb)&&guards(f->ib)&&guards(f->wb)&&guards(f->out),"input/output guards changed");need(!memcmp(myds_metal_buffer_data(f->xb.body),f->x.bytes,f->x.length)&&!memcmp(myds_metal_buffer_data(f->ib.body),f->ids.bytes,f->ids.length)&&!memcmp(myds_metal_buffer_data(f->wb.body),f->weights.bytes,f->weights.length),"original input bytes changed");need(finite_f32(myds_metal_buffer_data(f->out.body),f->out.bytes)&&written(myds_metal_buffer_data(f->out.body),f->out.bytes),"complete finite written output");}
